            "diff": "--- a/skills/evidentloop-review/rules/builtin.json\n+++ b/skills/evidentloop-review/rules/builtin.json\n@@ -0,0 +1,51 @@\n+{\n+  \"schemaVersion\": 1,\n+  \"kind\": \"builtin\",\n+  \"rules\": [\n+    {\n+      \"id\": \"logic.boundary\",\n+      \"category\": \"logic\",\n+      \"title\": \"边界条件与空值\"\n+    },\n+    {\n+      \"id\": \"logic.error-handling\",\n+      \"category\": \"logic\",\n+      \"title\": \"异常与失败路径\"\n+    },\n+    {\n+      \"id\": \"logic.concurrency\",\n+      \"category\": \"logic\",\n+      \"title\": \"并发与竞态\"\n+    },\n+    {\n+      \"id\": \"logic.state\",\n+      \"category\": \"logic\",\n+      \"title\": \"状态与数据一致性\"\n+    },\n+    {\n+      \"id\": \"security.injection\",\n+      \"category\": \"security\",\n+      \"title\": \"注入\"\n+    },\n+    {\n+      \"id\": \"security.authz\",\n+      \"category\": \"security\",\n+      \"title\": \"鉴权与越权\"\n+    },\n+    {\n+      \"id\": \"security.secret\",\n+      \"category\": \"security\",\n+      \"title\": \"敏感信息泄露\"\n+    },\n+    {\n+      \"id\": \"performance.complexity\",\n+      \"category\": \"performance\",\n+      \"title\": \"复杂度与重复计算\"\n+    },\n+    {\n+      \"id\": \"performance.io\",\n+      \"category\": \"performance\",\n+      \"title\": \"重复请求与 I/O\"\n+    }\n+  ]\n+}\n"
